	nodes: ReadonlyArray<AnyNode>,
	startPath: ReadonlyArray<number>,
	builder: ChunkBuilder,
	context: CollectionContext,
	repeat: { readonly id: string; readonly itemName: string } | null,
): number {
	const prefix = startPath.slice(0, -1);
