function resolveComponentLocalReferences(
	node: AnyNode | undefined,
	bindings: ReadonlyMap<string, ComponentLocalBinding>,
	state: WalkState,
	isRootScope: boolean,
	shadowed: ReadonlySet<string>,
): void {
	if (!node) return;
